sourcesContent:
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

import './Prediction.css';
import backgroundImage from '../assets/background.jpg';
import sunIcon from '../assets/sun.png';
import moonIcon from '../assets/moon.png';
import sendIcon from '../assets/send.png';

const translations = {
  en: {
    languageLabel: 'Language:',
    yes: 'yes',
    no: 'no',
    startOver: 'Start Over',
    home: '🏠 Home',
    visualization: '📊 Visualization',
    darkModeOn: 'Dark Mode',
    darkModeOff: 'Light Mode',
    typing: 'Typing...',
    questions: [
      "How old are you?",
      "What is your gender?",
      "What's your BMI (Body Mass Index)?",
      "What's your HbA1c Level (%)?",
      "What's your Blood Glucose Level (mg/dL)?",
      "Do you have hypertension?",
      "Do you have heart disease?",
      "What is your smoking history?"
    ],
    genderOptions: ['Female', 'Male', 'Other'],
    smokingOptions: ['never', 'former', 'current', 'not current', 'ever'],
    generalAdviceTitle: "🌟 General Tips:",
    generalAdvice: [
      '🩺 Monitor your blood sugar levels regularly.',
      '⚖️ Maintain a healthy weight.',
      '🏃 Stay physically active (at least 150 minutes/week).',
      '📅 Get regular check-ups with your doctor.',
    ],
    dietAdviceTitle: "🍎 Dietary Advice:",
    dietAdvice: [
      '🥦 Eat plenty of non-starchy vegetables.',
      '🌾 Choose whole grains over refined ones.',
      '🥤 Limit sugary drinks and juices.',
      '🥑 Include healthy fats like avocados and nuts.',
    ],
    warningSignsTitle: "⚠️ Watch for these warning signs:",
    warningSigns: [
      '🚽 Frequent urination.',
      '😰 Excessive thirst.',
      '📉 Unexplained weight loss.',
      '😴 Fatigue and blurred vision.',
    ],
    startMessage1: "Hi there! 👋 I'm your Diabetes Risk Assistant.",
    startMessage2: "Let's get started!",
    thankYou: "Thank you for your answers. Calculating your risk...",
    riskResult: (risk) => `Your predicted diabetes risk is: ${risk}%`,
    fallbackRisk: (risk) => `Based on your inputs, your estimated risk is: ${risk}%`,
    adviceQuestion: "Would you like some advice on how to reduce diabetes risk?",
    adviceYesNo: ['yes', 'no'],
    pleaseYesNo: "Please answer 'yes' or 'no'.",
    pleaseChoose: (opts) => `Please choose one of: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Please enter a number between ${min} and ${max}`,
    alrightAdviceDeclined: "Alright, feel free to come back anytime if you need advice.",
    okayMoreAdvice: "Okay, feel free to ask for more advice anytime!",
    allAdviceDone: "That's all the advice for now. Stay healthy! 💙",
    consultDoctor: "Remember to consult with your doctor for personalized advice.",
  },
  fr: {
    languageLabel: 'Langue :',
    yes: 'oui',
    no: 'non',
    startOver: 'Recommencer',
    home: '🏠 Accueil',
    visualization: '📊 Visualisation',
    darkModeOn: 'Mode Sombre',
    darkModeOff: 'Mode Clair',
    typing: 'En train d\'écrire...',
    questions: [
      "Quel âge avez-vous ?",
      "Quel est votre genre ?",
      "Quel est votre IMC (Indice de Masse Corporelle) ?",
      "Quel est votre taux d'HbA1c (%) ?",
      "Quel est votre taux de glucose sanguin (mg/dL) ?",
      "Avez-vous de l'hypertension ?",
      "Avez-vous une maladie cardiaque ?",
      "Quel est votre historique tabagique ?"
    ],
    genderOptions: ['Femme', 'Homme', 'Autre'],
    smokingOptions: ['jamais', 'ancien', 'actuel', 'pas actuel', 'déjà fumé'],
    generalAdviceTitle: "🌟 Conseils généraux :",
    generalAdvice: [
      '🩺 Surveillez régulièrement votre glycémie.',
      '⚖️ Maintenez un poids sain.',
      '🏃 Restez physiquement actif (au moins 150 minutes/semaine).',
      '📅 Faites des contrôles réguliers chez votre médecin.',
    ],
    dietAdviceTitle: "🍎 Conseils diététiques :",
    dietAdvice: [
      '🥦 Mangez beaucoup de légumes non féculents.',
      '🌾 Choisissez des grains entiers plutôt que raffinés.',
      '🥤 Limitez les boissons sucrées et les jus.',
      '🥑 Incluez des graisses saines comme les avocats et les noix.',
    ],
    warningSignsTitle: "⚠️ Surveillez ces signes d'alerte :",
    warningSigns: [
      '🚽 Mictions fréquentes.',
      '😰 Soif excessive.',
      '📉 Perte de poids inexpliquée.',
      '😴 Fatigue et vision floue.',
    ],
    startMessage1: "Bonjour ! 👋 Je suis votre assistant pour le risque de diabète.",
    startMessage2: "Commençons !",
    thankYou: "Merci pour vos réponses. Calcul du risque...",
    riskResult: (risk) => `Votre risque de diabète prédit est : ${risk}%`,
    fallbackRisk: (risk) => `Selon vos données, votre risque estimé est : ${risk}%`,
    adviceQuestion: "Souhaitez-vous des conseils pour réduire le risque de diabète ?",
    adviceYesNo: ['oui', 'non'],
    pleaseYesNo: "Veuillez répondre par 'oui' ou 'non'.",
    pleaseChoose: (opts) => `Veuillez choisir parmi : ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Veuillez entrer un nombre entre ${min} et ${max}`,
    alrightAdviceDeclined: "D'accord, revenez quand vous voulez pour des conseils.",
    okayMoreAdvice: "D'accord, n'hésitez pas à demander plus de conseils !",
    allAdviceDone: "Voilà tous les conseils pour le moment. Restez en bonne santé ! 💙",
    consultDoctor: "N'oubliez pas de consulter votre médecin pour des conseils personnalisés.",
  },
  ar: {
    languageLabel: 'اللغة:',
    yes: 'نعم',
    no: 'لا',
    startOver: 'ابدأ من جديد',
    home: '🏠 الصفحة الرئيسية',
    visualization: '📊 التمثيل البياني',
    darkModeOn: 'الوضع الداكن',
    darkModeOff: 'الوضع الفاتح',
    typing: '...يكتب',
    questions: [
      "كم عمرك؟",
      "ما هو جنسك؟",
      "ما هو مؤشر كتلة الجسم (BMI) الخاص بك؟",
      "ما هو مستوى HbA1c (%) الخاص بك؟",
      "ما هو مستوى جلوكوز الدم (mg/dL) الخاص بك؟",
      "هل تعاني من ارتفاع ضغط الدم؟",
      "هل تعاني من أمراض القلب؟",
      "ما هو تاريخ تدخينك؟"
    ],
    genderOptions: ['أنثى', 'ذكر', 'آخر'],
    smokingOptions: ['أبدا', 'سابق', 'حالي', 'ليس حاليا', 'سبق'],
    generalAdviceTitle: "🌟 نصائح عامة:",
    generalAdvice: [
      '🩺 راقب مستويات السكر في الدم بانتظام.',
      '⚖️ حافظ على وزن صحي.',
      '🏃 كن نشيطاً بدنيا (150 دقيقة على الأقل في الأسبوع).',
      '📅 قم بالفحوصات الدورية مع طبيبك.',
    ],
    dietAdviceTitle: "🍎 نصائح غذائية:",
    dietAdvice: [
      '🥦 تناول الكثير من الخضروات غير النشوية.',
      '🌾 اختر الحبوب الكاملة بدلاً من المكررة.',
      '🥤 قلل من المشروبات والعصائر المحلاة.',
      '🥑 أدرج الدهون الصحية مثل الأفوكادو والمكسرات.',
    ],
    warningSignsTitle: "⚠️ راقب علامات التحذير التالية:",
    warningSigns: [
      '🚽 كثرة التبول.',
      '😰 العطش المفرط.',
      '📉 فقدان الوزن غير المبرر.',
      '😴 التعب وتشوش الرؤية.',
    ],
    startMessage1: "مرحباً! 👋 أنا مساعدك في تقييم خطر الإصابة بالسكري.",
    startMessage2: "لنبدأ!",
    thankYou: "شكراً لإجاباتك. جارٍ حساب الخطر...",
    riskResult: (risk) => `مخاطر الإصابة بالسكري المتوقعة لديك هي: ${risk}%`,
    fallbackRisk: (risk) => `بناءً على مدخلاتك، تقدير الخطر هو: ${risk}%`,
    adviceQuestion: "هل ترغب في بعض النصائح لتقليل خطر الإصابة بالسكري؟",
    adviceYesNo: ['نعم', 'لا'],
    pleaseYesNo: "يرجى الرد بـ 'نعم' أو 'لا'.",
    pleaseChoose: (opts) => `يرجى اختيار واحد من: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `يرجى إدخال رقم بين ${min} و ${max}`,
    alrightAdviceDeclined: "حسناً، لا تتردد في العودة للحصول على نصائح في أي وقت.",
    okayMoreAdvice: "حسناً، يمكنك طلب المزيد من النصائح في أي وقت!",
    allAdviceDone: "هذه هي كل النصائح حتى الآن. حافظ على صحتك! 💙",
    consultDoctor: "تذكر استشارة طبيبك للحصول على نصائح شخصية.",
  }
};

const ageRange = [1, 120];
const hba1cRange = [3, 20]; // typical HbA1c range in %
const glucoseRange = [50, 600]; // blood glucose mg/dL
const bmiRange = [10, 60];

const defaultLanguage = 'en';

export default function Prediction() {
  const [language, setLanguage] = useState(defaultLanguage);
  const [darkMode, setDarkMode] = useState(false);

  const [chatHistory, setChatHistory] = useState([]);
  const [input, setInput] = useState('');
  const [currentStep, setCurrentStep] = useState(0);
  const [waitingForAdvice, setWaitingForAdvice] = useState(false);
  const [adviceStage, setAdviceStage] = useState(0);
  const [userData, setUserData] = useState({
    age: null,
    gender: null,
    bmi: null,
    hba1c: null,
    glucose: null,
    hypertension: null,
    heartDisease: null,
    smoking: null,
  });

  const navigate = useNavigate();
  const inputRef = useRef(null);

  // Initial greeting messages
  useEffect(() => {
    const t = translations[language];
    addBotMessage(t.startMessage1);
    setTimeout(() => addBotMessage(t.startMessage2), 1200);
  }, [language]);

  // Scroll chat to bottom on new message
  useEffect(() => {
    const chatBox = document.getElementById('chatBox');
    if (chatBox) chatBox.scrollTop = chatBox.scrollHeight;
  }, [chatHistory]);

  // Add bot message helper
  function addBotMessage(text) {
    setChatHistory((h) => [...h, { sender: 'bot', text }]);
  }

  // Add user message helper
  function addUserMessage(text) {
    setChatHistory((h) => [...h, { sender: 'user', text }]);
  }

  // Handle language change
  function handleLanguageChange(e) {
    setLanguage(e.target.value);
    resetChat();
  }

  // Handle dark mode toggle
  function toggleDarkMode() {
    setDarkMode((prev) => !prev);
  }

  // Reset chat and state to start over
  function resetChat() {
    setChatHistory([]);
    setInput('');
    setCurrentStep(0);
    setWaitingForAdvice(false);
    setAdviceStage(0);
    setUserData({
      age: null,
      gender: null,
      bmi: null,
      hba1c: null,
      glucose: null,
      hypertension: null,
      heartDisease: null,
      smoking: null,
    });
  }

  // Validate numeric input
  function validateNumber(inputStr, min, max) {
    const val = Number(inputStr);
    return !isNaN(val) && val >= min && val <= max;
  }

  // Validate yes/no input for language
  function validateYesNo(inputStr) {
    const t = translations[language];
    const low = inputStr.trim().toLowerCase();
    return [t.yes.toLowerCase(), t.no.toLowerCase()].includes(low);
  }

  // Validate gender input
  function validateGender(inputStr) {
    const t = translations[language];
    return t.genderOptions.map(g => g.toLowerCase()).includes(inputStr.trim().toLowerCase());
  }

  // Validate smoking input
  function validateSmoking(inputStr) {
    const t = translations[language];
    return t.smokingOptions.map(s => s.toLowerCase()).includes(inputStr.trim().toLowerCase());
  }

  // Convert yes/no to boolean
  function yesNoToBool(inputStr) {
    const t = translations[language];
    const low = inputStr.trim().toLowerCase();
    if (low === t.yes.toLowerCase()) return true;
    if (low === t.no.toLowerCase()) return false;
    return null;
  }

  // Convert gender to standardized string
  function normalizeGender(inputStr) {
    const t = translations[language];
    const low = inputStr.trim().toLowerCase();
    const idx = t.genderOptions.map(g => g.toLowerCase()).indexOf(low);
    if (idx !== -1) return t.genderOptions[idx];
    return null;
  }

  // Convert smoking to standardized string
  function normalizeSmoking(inputStr) {
    const t = translations[language];
    const low = inputStr.trim().toLowerCase();
    const idx = t.smokingOptions.map(s => s.toLowerCase()).indexOf(low);
    if (idx !== -1) return t.smokingOptions[idx];
    return null;
  }

  // Handle user input submit
  function handleSubmit(e) {
    e.preventDefault();
    const trimmedInput = input.trim();
    if (!trimmedInput) return;
    const t = translations[language];

    addUserMessage(trimmedInput);
    setInput('');

    if (waitingForAdvice) {
      // Advice yes/no step
      const lowInput = trimmedInput.toLowerCase();
      if ([t.yes.toLowerCase(), t.no.toLowerCase()].includes(lowInput)) {
        if (lowInput === t.yes.toLowerCase()) {
          provideAdvice();
        } else {
          addBotMessage(t.alrightAdviceDeclined);
          setWaitingForAdvice(false);
          setAdviceStage(0);
          setCurrentStep(t.questions.length); // End
        }
      } else {
        addBotMessage(t.pleaseYesNo);
      }
      return;
    }

    // Main Q&A validation and storing answers
    switch (currentStep) {
      case 0: // Age
        if (!validateNumber(trimmedInput, ...ageRange)) {
          addBotMessage(t.enterNumberBetween(ageRange[0], ageRange[1]));

        } else {
          setUserData((u) => ({ ...u, age: Number(trimmedInput) }));
          nextStep();
        }
        break;
      case 1: // Gender
        if (!validateGender(trimmedInput)) {
          addBotMessage(t.pleaseChoose(t.genderOptions));
        } else {
          setUserData((u) => ({ ...u, gender: normalizeGender(trimmedInput) }));
          nextStep();
        }
        break;
      case 2: // BMI
        if (!validateNumber(trimmedInput, ...bmiRange)) {
          addBotMessage(t.enterNumberBetween(bmiRange[0], bmiRange[1]));
        } else {
          setUserData((u) => ({ ...u, bmi: Number(trimmedInput) }));
          nextStep();
        }
        break;
      case 3: // HbA1c
        if (!validateNumber(trimmedInput, ...hba1cRange)) {
          addBotMessage(t.enterNumberBetween(hba1cRange[0], hba1cRange[1]));
        } else {
          setUserData((u) => ({ ...u, hba1c: Number(trimmedInput) }));
          nextStep();
        }
        break;
      case 4: // Glucose
        if (!validateNumber(trimmedInput, ...glucoseRange)) {
          addBotMessage(t.enterNumberBetween(glucoseRange[0], glucoseRange[1]));
        } else {
          setUserData((u) => ({ ...u, glucose: Number(trimmedInput) }));
          nextStep();
        }
        break;
      case 5: // Hypertension yes/no
        if (!validateYesNo(trimmedInput)) {
          addBotMessage(t.pleaseYesNo);
        } else {
          setUserData((u) => ({ ...u, hypertension: yesNoToBool(trimmedInput) }));
          nextStep();
        }
        break;
      case 6: // Heart disease yes/no
        if (!validateYesNo(trimmedInput)) {
          addBotMessage(t.pleaseYesNo);
        } else {
          setUserData((u) => ({ ...u, heartDisease: yesNoToBool(trimmedInput) }));
          nextStep();
        }
        break;
      case 7: // Smoking history
        if (!validateSmoking(trimmedInput)) {
          addBotMessage(t.pleaseChoose(t.smokingOptions));
        } else {
          setUserData((u) => ({ ...u, smoking: normalizeSmoking(trimmedInput) }));
          nextStep();
        }
        break;
      default:
        addBotMessage("Oops, something went wrong.");
    }
  }

  // Proceed to next step or finalize
  function nextStep() {
    const t = translations[language];
    if (currentStep + 1 < t.questions.length) {
      setCurrentStep(currentStep + 1);
      setTimeout(() => addBotMessage(t.questions[currentStep + 1]), 800);
    } else {
      // End of questions, calculate risk
      setCurrentStep(currentStep + 1);
      addBotMessage(t.thankYou);
      setTimeout(() => {
        const risk = calculateRisk();
        addBotMessage(t.riskResult(risk));
        setTimeout(() => {
          addBotMessage(t.adviceQuestion);
          setWaitingForAdvice(true);
        }, 1500);
      }, 1500);
    }
  }

  // Simple diabetes risk calculation (dummy example)
  function calculateRisk() {
    const u = userData;
    const t = translations[language];
    // Simple weighted sum heuristic (example)
    let risk = 5; // base risk

    if (u.age) risk += (u.age - 20) * 0.3;
    if (u.bmi) risk += (u.bmi - 18) * 1.5;
    if (u.hba1c) risk += (u.hba1c - 5) * 5;
    if (u.glucose) risk += (u.glucose - 70) * 0.2;
    if (u.hypertension) risk += 5;
    if (u.heartDisease) risk += 7;
    if (u.smoking === t.smokingOptions[2].toLowerCase()) risk += 5; // current smoker

    risk = Math.min(Math.max(Math.round(risk), 0), 100);
    return risk;
  }

  // Advice sets for cycling
  const adviceSets = [
    {
      titleKey: 'generalAdviceTitle',
      advicesKey: 'generalAdvice',
    },
    {
      titleKey: 'dietAdviceTitle',
      advicesKey: 'dietAdvice',
    },
    {
      titleKey: 'warningSignsTitle',
      advicesKey: 'warningSigns',
    },
  ];

  // Provide advice messages one set at a time
  function provideAdvice() {
    const t = translations[language];
    if (adviceStage < adviceSets.length) {
      const set = adviceSets[adviceStage];
      addBotMessage(t[set.titleKey]);
      t[set.advicesKey].forEach((line) => addBotMessage(line));
      setAdviceStage(adviceStage + 1);
      setWaitingForAdvice(true);
      addBotMessage(t.adviceQuestion);
    } else {
      addBotMessage(t.allAdviceDone);
      addBotMessage(t.consultDoctor);
      setWaitingForAdvice(false);
      setAdviceStage(0);
    }
  }

  // On load or language change, start first question after greetings
  useEffect(() => {
    const t = translations[language];
    if (chatHistory.length === 2) {
      setTimeout(() => addBotMessage(t.questions[0]), 1500);
    }
  }, [language, chatHistory.length, translations]);

  return (
    <div className={`prediction-page ${darkMode ? 'dark' : 'light'}`} style={{ backgroundImage: `url(${backgroundImage})` }}>
      <div className="overlay" />

      {/* Header */}
      <header className="header">
        <nav>
          <button className="nav-button" onClick={() => navigate('/')}>
            {translations[language].home}
          </button>
          <button className="nav-button" onClick={() => navigate('/visualization')}>
            {translations[language].visualization}
          </button>
        </nav>

        <div className="language-theme-controls">
          <label htmlFor="language-select">{translations[language].languageLabel}</label>
          <select id="language-select" value={language} onChange={handleLanguageChange} aria-label="Select language">
            <option value="en">English</option>
            <option value="fr">Français</option>
            <option value="ar">العربية</option>
          </select>

          <button className="theme-toggle" onClick={toggleDarkMode} aria-label="Toggle dark/light mode">
            <img src={darkMode ? sunIcon : moonIcon} alt={darkMode ? 'Light Mode' : 'Dark Mode'} />
          </button>
        </div>
      </header>

      {/* Chatbox */}
      <main className="chat-container" id="chatBox" role="log" aria-live="polite" aria-relevant="additions">
        {chatHistory.map((msg, idx) => (
          <div
            key={idx}
            className={`chat-message ${msg.sender === 'bot' ? 'bot' : 'user'}`}
            lang={language === 'ar' ? 'ar' : 'en'}
            dir={language === 'ar' ? 'rtl' : 'ltr'}
          >
            {msg.text}
          </div>
        ))}
        {waitingForAdvice && <div className="chat-message bot typing-indicator">{translations[language].typing}</div>}
      </main>

      {/* Input Form */}
      <form className="input-form" onSubmit={handleSubmit} aria-label="Chat input form">
        <input
          ref={inputRef}
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Type your answer..."
          aria-required="true"
          aria-label="Your answer"
          autoComplete="off"
          autoFocus
          dir={language === 'ar' ? 'rtl' : 'ltr'}
        />
        <button type="submit" aria-label="Send answer">
          <img src={sendIcon} alt="Send" />
        </button>
      </form>

      {/* Restart Button */}
      <button className="restart-button" onClick={resetChat}>
        {translations[language].startOver}
      </button>
    </div>
  );
}
